import time
from typing import TYPE_CHECKING, Dict, List, Optional, Any
from taf.ul.sbts.energy_saving.decorators.connection import with_connection
from taf.ul.sbts.energy_saving.exceptions import DeltaError

if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


class EnergySetupWorkflow:
    """Workflow for complete energy saving setup."""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    @with_connection
    def setup_complete_energy_saving(
            self,
            xml_scf,
            include_4g: bool = True,
            include_5g: bool = True,
            force_recreate_groups: bool = False,
            cell_nr_filter_params: Optional[Dict] = None,
            cell_lte_filter_params:  Optional[Dict] = None,
            connection: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
    Complete energy saving setup for both 4G and 5G.

        Args:
            xml_scf: Parsed SCF XML
            include_4g: Whether to include LTE cells
            include_5g: Whether to include NR cells
            force_recreate_groups: Whether to delete existing groups and create new ones
            cell_filter_params: Parameters to filter cells for energy saving

        Returns:
            Dict with power group DNs: {
                "nrpgrp_dns": [...],
                "psgrp_dns": [...],
                "errors": [...],
                "coordination_enabled": bool,
            }
        """

        errors: List[str] = []
        results: Dict[str, Any] = {
            "nrpgrp_dns": [],
            "psgrp_dns": [],
            "errors": errors,
            "coordination_enabled": False
        }
        nrpgrp_dns = []
        psgrp_dns = []
        if include_5g:
            try:
                nrpgrp_dns = self.try_to_enable_5g_energy_saving(
                    xml_scf,
                    force_recreate_groups,
                    filter_cell_list=cell_nr_filter_params,
                    connection=connection,
                )
                results['nrpgrp_dns'] = nrpgrp_dns
            except DeltaError as e:
                errors.append(f"5G energy saving setup failed: {e}, please adjust manually SCF")

        if include_4g:
            try:
                psgrp_dns = self.try_to_enable_4g_energy_saving(
                    xml_scf,
                    force_recreate_groups,
                    filter_cell_list=cell_lte_filter_params,
                    connection=connection,
                )
                results['psgrp_dns'] = psgrp_dns
            except DeltaError as e:
                errors.append(f"4G energy saving setup failed: {e}, please adjust manually SCF")

        if nrpgrp_dns and psgrp_dns:
            try:
                self.try_to_enable_4g5g_coordination(xml_scf)
                results["coordination_enabled"] = True
            except DeltaError as e:
                errors.append(f"4G+5G coordination setup failed: {e}, skipping coordination setup")

        return results

    @with_connection
    def try_to_enable_4g_energy_saving(
            self,
            xml_scf,
            force_recreate_groups,
            filter_cell_list=None,
            connection=None,
    ) -> Dict[str, List[int]]:
        """Try to enable 4G energy saving."""
        filter_list = filter_cell_list if filter_cell_list else []
        filtered_cell_distnames = self.context.lncel_manager.get_filtered_cells_by_params(xml_scf, filter_list)
        filtered_cell_ids = [int(dn.split("-")[-1]) for dn in filtered_cell_distnames]
        if not filtered_cell_distnames:
            return {}

        lnbts_distname = self.context.scf_manager.get_lnbts_distnames(xml_scf)[0]
        result = self.check_if_actLBPowerSaving_enabled(xml_scf, lnbts_distname)
        power_group_dns = self.context.psgrp_manager.get_existing_power_group_dist_names_from_scf(xml_scf)

        if not power_group_dns:
            force_recreate_groups = True

        if force_recreate_groups:
            used_ids = []
            with self.context.delta_manager.delta_context(connection_alias=connection) as delta_id:
                for dn in power_group_dns:
                    self.context.delta_manager.append_managed_object_to_delta(dn, operation="delete", delta_id=delta_id)
                    used_ids.append(int(dn.split("-")[-1]))
                power_group_dns = {}
                group_ids = self._get_unused_group_ids(len(filtered_cell_ids), used_ids)
                for group_id, cell_id in zip(group_ids, filtered_cell_ids):
                    group_dn = self.context.psgrp_manager.add_recommended_power_group_object_to_delta(
                        lnbts_distname,
                        cells_id=[cell_id],
                        group_id=group_id,
                        delta_id=delta_id,
                    )
                    power_group_dns[group_dn] = [cell_id]
                self.add_actLBPowerSaving_to_delta(lnbts_distname, True, delta_id=delta_id)
        else:
            if result is False:
                with self.context.delta_manager.delta_context(connection_alias=connection) as delta_id:
                    self.add_actLBPowerSaving_to_delta(lnbts_distname, True, delta_id=delta_id)
            power_group_dns = {dn: self.context.psgrp_manager.get_cell_ids_from_lbpsCellList(xml_scf, dn)
                               for dn in power_group_dns}

        return power_group_dns

    @with_connection
    def try_to_enable_5g_energy_saving(
            self,
            xml_scf,
            force_recreate_groups,
            filter_cell_list=None,
            connection=None,
    ) -> Dict[str, List[int]]:
        """Try to enable 5G energy saving."""
        filter_list = filter_cell_list if filter_cell_list else []
        filtered_cell_distnames = self.context.nrcell_manager.get_filtered_cells_by_params(xml_scf, filter_list)
        filtered_cell_ids = [int(dn.split("-")[-1]) for dn in filtered_cell_distnames]
        if not filtered_cell_distnames:
            return {}

        nrbts_distname = self.context.scf_manager.get_nrbts_distnames(xml_scf)[0]
        result = self.check_if_actNrLBPowerSaving_enabled(xml_scf, nrbts_distname)
        power_group_dns = self.context.nrpgrp_manager.get_existing_power_group_dist_names_from_scf(xml_scf)
        if not power_group_dns:
            force_recreate_groups = True

        if force_recreate_groups:
            used_ids = []
            with self.context.delta_manager.delta_context(connection_alias=connection) as delta_id:
                for dn in power_group_dns:
                    self.context.delta_manager.append_managed_object_to_delta(dn, operation="delete", delta_id=delta_id)
                    used_ids.append(int(dn.split("-")[-1]))
                power_group_dns = {}
                group_ids = self._get_unused_group_ids(len(filtered_cell_ids), used_ids)
                for group_id, cell_id in zip(group_ids, filtered_cell_ids):
                    group_dn = (
                        self.context.nrpgrp_manager.add_recommended_power_group_object_to_delta(
                            nrbts_distname,
                            cells_id=[cell_id],
                            group_id=group_id,
                            delta_id=delta_id,
                        )
                    )
                    power_group_dns[group_dn] = [cell_id]
                self.add_actNrLBPowerSaving_to_delta(nrbts_distname, True, delta_id=delta_id)
        else:
            if result is False:
                with self.context.delta_manager.delta_context(connection_alias=connection) as delta_id:
                    self.add_actNrLBPowerSaving_to_delta(nrbts_distname, True, delta_id=delta_id)
            power_group_dns = {dn: self.context.nrpgrp_manager.get_cell_ids_from_lbpsCellList(xml_scf, dn)
                               for dn in power_group_dns}

        return power_group_dns

    def try_to_enable_4g5g_coordination(self, xml_scf, delta_id: int = 0):
        """Try to enable 4G+5G coordination."""
        nrbts_distname = self.context.scf_manager.get_nrbts_distnames(xml_scf)[0]
        lnbts_distname = self.context.scf_manager.get_lnbts_distnames(xml_scf)[0]
        nrbts_4g5g, lnbts_4g5g = self.check_if_actCoordinated4g5gPowerSaving_enabled(
            xml_scf, nrbts_distname, lnbts_distname
        )
        if nrbts_4g5g and lnbts_4g5g:
            return True
        with self.context.delta_manager.delta_context() as delta_id:
            if not nrbts_4g5g:
                self.add_actCoordinated4g5gPowerSaving_to_delta(nrbts_distname, "cellDeactivation", delta_id)
            if not lnbts_4g5g:
                self.add_actCoordinated4g5gPowerSaving_to_delta(lnbts_distname, "cellDeactivation", delta_id)
        return True

    def _get_unused_group_ids(self, ids_amount: int, used_ids: List[int], start: int = 0, stop: int = 256) -> List[int]:
        """Return a list of free group IDs within [start, stop). Fills gaps first."""
        free = []
        used = {int(x) for x in used_ids}
        for gid in range(start, stop):
            if gid not in used:
                free.append(gid)
                if len(free) >= ids_amount:
                    break
        return free

    def check_if_actNrLBPowerSaving_enabled(self, xml_scf, nrbts_distname) -> bool:
        """Check if actNrLBPowerSaving is enabled."""
        nrbts_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, nrbts_distname)
        if nrbts_params and nrbts_params.get("actNrLBPowerSaving", "false").lower() == "true":
            return True
        return False

    def check_if_actLBPowerSaving_enabled(self, xml_scf, lnbts_distname) -> bool:
        """Check if actLBPowerSaving is enabled."""
        lnbts_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, lnbts_distname)
        if lnbts_params and lnbts_params.get("actLBPowerSaving", "false").lower() == "true":
            return True
        return False

    def add_actNrLBPowerSaving_to_delta(self, nrbts_distname: str, value: bool, delta_id: int = 0):
        """Add actNrLBPowerSaving parameter update to delta."""
        self.context.delta_manager.append_parameter_update_to_delta(
            nrbts_distname, "actNrLBPowerSaving", value, delta_id
        )

    def add_actLBPowerSaving_to_delta(self, lnbts_distname: str, value: bool, delta_id: int = 0):
        """Add actLBPowerSaving parameter update to delta."""
        self.context.delta_manager.append_parameter_update_to_delta(
            lnbts_distname, "actLBPowerSaving", value, delta_id
        )

    def check_if_actCoordinated4g5gPowerSaving_enabled(self, xml_scf, nrbts_distname, lnbts_distname):
        """Check if 4G+5G coordination is supported."""
        nrbts_4g5g, lnbts_4g5g = False, False
        nrbts_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, nrbts_distname)
        lnbts_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, lnbts_distname)
        if nrbts_params.get("actCoordinated4g5gPowerSaving", "disabled").lower() != "disabled":
            nrbts_4g5g = True

        if lnbts_params.get("actCoordinated4g5gPowerSaving", "disabled").lower() != "disabled":
            lnbts_4g5g = True

        return nrbts_4g5g, lnbts_4g5g

    def add_actCoordinated4g5gPowerSaving_to_delta(self, subbts_distname, value, delta_id: int = 0):
        """Enable 4G+5G coordination."""
        self.context.delta_manager.append_parameter_update_to_delta(
            subbts_distname, "actCoordinated4g5gPowerSaving", value, delta_id
        )

    @with_connection
    def wait_until_any_cell_in_energy_saving(self, cell_type: str, timeout=300, check_interval=10, connection=None):
        """Wait until any cell is in energy saving."""
        start_time = time.monotonic()
        while time.monotonic() - start_time < timeout:
            if self.check_if_any_cell_in_energy_saving(cell_type, timeout=60, connection=connection):
                return True
            time.sleep(check_interval)
        return False

    @with_connection
    def wait_until_all_cells_in_energy_saving(self, cell_type: str, cell_ids=None, timeout=300, check_interval=10,
                                              allowed_missing: int = 0, connection=None):
        """Wait until all (minus allowed_missing) cells are in energy saving."""
        start_time = time.monotonic()
        while time.monotonic() - start_time < timeout:
            if self.check_if_all_cells_in_energy_saving(
                cell_type,
                cell_ids=cell_ids,
                timeout=60,
                allowed_missing=allowed_missing,
                connection=connection
            ):
                return True
            time.sleep(check_interval)
        return False

    @with_connection
    def check_if_any_cell_in_energy_saving(self, cell_type: str, timeout=60, connection=None) -> bool:
        """Check if any cell is in energy saving."""
        cell_manager = self.context.nrcell_manager if cell_type.lower() == "nr" else self.context.lncel_manager
        cell_statuses = cell_manager.get_cells_statuses(timeout=timeout, connection=connection)
        for cell_status in cell_statuses.values():
            if self.check_if_cell_in_energy_saving(cell_status):
                return True
        return False

    @with_connection
    def check_if_all_cells_in_energy_saving(self, cell_type, cell_ids=None, timeout=60,
                                            allowed_missing: int = 0, connection=None) -> bool:
        """Check if all (minus allowed_missing) cells are in energy saving."""
        cell_manager = self.context.nrcell_manager if cell_type.lower() == "nr" else self.context.lncel_manager
        cell_statuses = cell_manager.get_cells_statuses(timeout=timeout, connection=connection)
        if cell_ids:
            cell_statuses = {cid: status for cid, status in cell_statuses.items() if cid in cell_ids}

        not_in = 0
        for status in cell_statuses.values():
            if not self.check_if_cell_in_energy_saving(status):
                not_in += 1
                if not_in > allowed_missing:
                    return False
        return True

    def get_allowed_missing_cells_count(self, cell_type, xml_scf, power_group_dns) -> int:
        """Get allowed missing cells count"""
        allowed_missing_cells = 0
        power_group_manager = self.context.nrpgrp_manager if cell_type.lower() == "nr" else self.context.psgrp_manager
        for power_group_dn in power_group_dns:
            lbpsLastCellSOEnabled = power_group_manager.get_lbpsLastCellSOEnabled_param(xml_scf, power_group_dn)
            if lbpsLastCellSOEnabled.lower() == "false":
                cells_with_order = power_group_manager.get_cell_ids_with_cells_order_from_lbpsCellList(xml_scf,
                                                                                                       power_group_dn)
                cells_with_order_100 = [cell_id for cell_id, order in cells_with_order.items() if order == 100]
                if cells_with_order_100:
                    allowed_missing_cells += len(cells_with_order_100)
                else:
                    allowed_missing_cells += 1
        return allowed_missing_cells

    @staticmethod
    def check_if_cell_in_energy_saving(cell_status):
        energy_saving_state = ("energySaving".lower(), "reducedEnergySaving".lower())
        if cell_status.get("energySavingState", "").lower() in energy_saving_state:
            return True
        return False

    @with_connection
    def disable_energy_saving(self, power_group_dns, connection=None):
        """Disable energy saving for given power groups."""
        self.context.psgrp_manager.disable_energy_saving_mode(power_group_dns, connection=connection)

    @with_connection
    def enable_energy_saving(self, power_group_dns, xml_scf=None, connection=None):
        """Enable energy saving for given power groups."""
        self.context.psgrp_manager.enable_energy_saving_mode(power_group_dns, xml_scf=xml_scf, connection=connection)
